"""Generate a single offline Korean explainer directly from the retained evidence."""
import pathlib,json,hashlib
E=pathlib.Path(__file__).resolve().parent
curves=json.loads((E/'curves.json').read_text());rows=[]
for host in ['rtx','spark']:
 for r in json.loads((E/'evidence'/host/'summary.json').read_text())['rows']:
  if r['primary']:rows.append({k:r.get(k) for k in ['label','host','mode','ues_per_cell','cells','bandwidth_mhz','ports','min_coverage','min_endpoint_ratio','cadence_covered_with_one_boundary_batch','strict_deadline_clean','measured_rebases','nodes','cpu_usage']})
R=E.parent/'rtx-scaling-20261102';S=E.parent/'multi-ue-affinity-20261102/evidence';live_r=json.loads((R/'comparison.json').read_text())['rows'];live_s=json.loads((S/'comparison.json').read_text())['rows']
live=[]
for n in [1,4,8,16]:
 a=next(r for r in live_r if r['ue_count']==n and r['layout']=='matched-r1');b=next((r for r in live_r if r['ue_count']==n and r['layout']=='pbroker-r1'),None);c=next(r for r in live_s if r['ues']==n and r['patch']=='on' and r['application_completed'])
 live.append(dict(ues=n,rtx=a['rate']['post_warmup']['ratio'],rtx_kpi=a['valid_kpi_windows'],rtx_swap=b['rate'].get('post_warmup',{}).get('ratio') if b else None,rtx_swap_tested=b is not None,spark=c['post']['ratio'],spark_kpi=c['valid_segments']))
payload=dict(curves=curves,rows=rows,live=live,conclusions=json.loads((E/'conclusions.json').read_text()))
